{"content":"/* ============================================================
   08-editorial.css — Twinthos editorial design system
   Source of truth for typography, hero, sections, nav, footer.
   Loads LAST in the CSS bundle. Supersedes 01–07.
   ============================================================ */

:root{
  --serif:"IBM Plex Serif",Georgia,serif;
  --serif-display:"IBM Plex Serif",Georgia,serif;
  --display:"Inter Tight","Inter",system-ui,sans-serif;
  --f:"Inter",system-ui,sans-serif;
  --mono:"Geist Mono","JetBrains Mono","SF Mono",ui-monospace,Menlo,monospace;
  --ink:#090B0A;
  --bg2:#111413;
  --paper:#F3F1EA;
  --paper-2:#EAE7DE;
  --light:#F5F5F0;
  --mute:#B9C2BB;
  --mute-on-paper:#5A6660;
  --emerald:#39DB9B;
  --emerald-2:#22B97C;
  --amber:#F0BE63;
  --ink-text:#1A1C1B;
  --line:rgba(243,241,234,.08);
  --line-2:rgba(243,241,234,.18);
  --line-on-paper:rgba(9,11,10,.12);
  --wrap:1280px;
  --gut:clamp(20px,4vw,40px);
  --nav:56px;
  --ease:cubic-bezier(.2,.7,.1,1);
  --ease-out:cubic-bezier(.2,.7,.1,1);
}

/* ----- Typography ----- */
body{font-family:var(--f);font-size:16px;line-height:1.55;color:var(--light);background:var(--ink);-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility;font-feature-settings:"ss01","cv11"}
.h1,h1{font-family:var(--display);font-size:clamp(40px,7.2vw,108px);font-weight:600;letter-spacing:-.032em;line-height:.98;margin:0;color:var(--light)}
.h2,h2{font-family:var(--display);font-size:clamp(32px,4.8vw,72px);font-weight:500;letter-spacing:-.022em;line-height:1.02;margin:0;color:var(--light);max-width:18em}
.h3,h3{font-family:var(--display);font-size:clamp(20px,2.2vw,28px);font-weight:500;letter-spacing:-.014em;line-height:1.18;margin:0}
.lead{font-family:var(--f);font-size:clamp(17px,1.4vw,21px);line-height:1.55;letter-spacing:-.005em;color:var(--mute);font-weight:400;max-width:42em;margin:0}
.small{font-size:14px;line-height:1.55;color:var(--mute);margin:0}
.micro{font-family:var(--mono);font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--mute);margin:0}
.eyebrow{font-family:var(--mono);font-size:11px;font-weight:500;letter-spacing:.14em;text-transform:uppercase;color:var(--mute);display:inline-flex;align-items:center;gap:10px;margin:0}
.dim{color:var(--mute);font-weight:400}
.dropcap::first-letter{font-family:var(--serif-display);font-style:italic;font-weight:400;float:left;font-size:3.6em;line-height:.85;padding:6px 12px 0 0;color:var(--light)}

/* ============================================================
   Hero — full-bleed motion reel + bottom CTAs bar.
   ============================================================ */
.hero.hx{position:relative;margin:0;padding:0;background:var(--ink);overflow:hidden}
.hx-stage{position:relative;width:100%;min-height:clamp(560px,86vh,920px);overflow:hidden;isolation:isolate;background:#050708}
.hx-video{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center;z-index:0;background:#050708}
.hx-veil{position:absolute;inset:0;z-index:1;pointer-events:none;background:linear-gradient(180deg,rgba(5,7,8,.78) 0%,rgba(5,7,8,.4) 35%,rgba(5,7,8,.6) 75%,rgba(5,7,8,.95) 100%)}
.hx-play{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);z-index:3;display:flex;align-items:center;gap:14px;padding:18px 28px;border-radius:999px;background:rgba(243,241,234,.96);color:#0A0C0B;font-family:var(--mono);font-size:12px;letter-spacing:.14em;text-transform:uppercase;border:0;cursor:pointer;opacity:0;pointer-events:none;transition:opacity .35s var(--ease-out),transform .35s var(--ease-out);backdrop-filter:blur(8px);box-shadow:0 30px 80px -20px rgba(0,0,0,.7)}
.hx-play.on{opacity:1;pointer-events:auto}
.hx-play:hover{transform:translate(-50%,-50%) scale(1.03)}
.hx-toggle{position:absolute;top:20px;right:20px;z-index:4;padding:7px 12px;border-radius:999px;background:rgba(5,7,8,.55);color:var(--light);font-family:var(--mono);font-size:10px;letter-spacing:.14em;text-transform:uppercase;border:1px solid rgba(243,241,234,.18);cursor:pointer;backdrop-filter:blur(8px);transition:background .25s var(--ease-out),border-color .25s var(--ease-out)}
.hx-toggle:hover{background:rgba(5,7,8,.75);border-color:rgba(243,241,234,.4)}
.hx-toggle .hx-toggle-off{display:none}
.hx-toggle[aria-pressed="false"] .hx-toggle-on{display:none}
.hx-toggle[aria-pressed="false"] .hx-toggle-off{display:inline}
.hx-meta{position:absolute;left:20px;bottom:20px;z-index:4;font-family:var(--mono);font-size:10px;letter-spacing:.12em;text-transform:uppercase;color:rgba(243,241,234,.55);padding:6px 10px;border-radius:2px;background:rgba(5,7,8,.45);backdrop-filter:blur(8px)}
.hx-h1-sr{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}

/* ----- Below the reel — CTAs bar ----- */
.hx-footbar-wrap{background:var(--ink);border-top:1px solid rgba(243,241,234,.08)}
.hx-footbar{max-width:var(--wrap);margin:0 auto;padding:clamp(20px,3vh,32px) var(--gut);display:flex;align-items:center;gap:clamp(14px,1.8vw,24px);flex-wrap:wrap}
.hx-footbar .btn{flex-shrink:0}
.hx-footprice{font-family:var(--mono);font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--mute);margin-left:auto;display:flex;gap:10px;align-items:center}
.hx-footprice b{color:var(--light);font-weight:500}
.btn-ghost-dark{background:transparent;border:1px solid rgba(243,241,234,.18);color:var(--light)}
.btn-ghost-dark:hover{background:rgba(243,241,234,.06);border-color:rgba(243,241,234,.3)}
@media (max-width:780px){
  .hx-footbar{flex-direction:column;align-items:stretch;gap:14px}
  .hx-footbar .btn{justify-content:center}
  .hx-footprice{margin-left:0;text-align:center;justify-content:center}
  .hx-stage{min-height:clamp(440px,68vh,680px)}
}
@media (max-width:480px){
  .hx-stage{min-height:clamp(380px,62vh,560px)}
  .hx-meta{left:14px;bottom:14px;font-size:9px}
  .hx-toggle{top:14px;right:14px;font-size:9px;padding:5px 10px}
}

/* ============================================================
   Buttons
   ============================================================ */
.hero-actions{display:flex;flex-wrap:wrap;gap:12px;align-items:center}
.btn{display:inline-flex;align-items:center;gap:10px;padding:14px 22px;border-radius:999px;font-family:var(--f);font-size:14px;font-weight:500;letter-spacing:-.005em;border:1px solid transparent;cursor:pointer;text-decoration:none;transition:background .25s var(--ease-out),color .25s var(--ease-out),border-color .25s var(--ease-out),transform .25s var(--ease-out)}
.btn .ar{margin-left:6px;transition:transform .25s var(--ease-out)}
.btn:hover .ar{transform:translateX(4px)}
.btn-paper{background:var(--paper);color:var(--ink-text);border-color:var(--paper)}
.btn-paper:hover{background:var(--light)}
.btn-ghost{background:transparent;color:var(--light);border-color:rgba(243,241,234,.3)}
.btn-ghost:hover{border-color:rgba(243,241,234,.7)}
.btn-ink{background:var(--ink-text);color:var(--paper);border-color:var(--ink-text)}
.btn-ink:hover{background:#000}
.btn-line{background:transparent;color:var(--ink-text);border-color:var(--ink-text)}
.btn-line:hover{background:var(--ink-text);color:var(--paper)}
.on-paper .btn-line{color:var(--ink-text);border-color:var(--ink-text)}
.btn-sm{padding:10px 16px;font-size:13px}

/* ============================================================
   Section header — 12-col editorial layout
   ============================================================ */
.sec-head{display:grid;grid-template-columns:repeat(12,1fr);gap:clamp(16px,2vw,32px);align-items:start;margin-bottom:clamp(40px,5vw,80px)}
.sec-idx{grid-column:1/span 2;display:flex;flex-direction:column;gap:14px}
.sec-idx .n{font-family:var(--display);font-size:clamp(96px,11vw,180px);font-weight:500;letter-spacing:-.05em;line-height:.85;color:var(--mute);font-feature-settings:"ss01","tnum"}
.sec-idx .eyebrow{color:var(--mute)}
.paper .sec-idx .n{color:rgba(9,11,10,.12)}
.sec-title{grid-column:3/span 10}
.sec-title .h2,.sec-title h2{margin-bottom:clamp(20px,2.6vw,32px)}
.sec-title .lead{max-width:46em}
.sec-title .h2 .dim,.sec-title h2 .dim{color:var(--mute);font-weight:400}

/* ============================================================
   Reveal animation
   ============================================================ */
.rv{opacity:0;transform:translateY(20px);transition:opacity .8s var(--ease-out),transform .8s var(--ease-out)}
.rv.in{opacity:1;transform:none}
.rv.delay-1{transition-delay:.1s}
.rv.delay-2{transition-delay:.2s}
.rv.delay-3{transition-delay:.3s}
@media (prefers-reduced-motion:reduce){.rv{opacity:1;transform:none;transition:none}}

/* ============================================================
   Section layout
   ============================================================ */
.section,.sec{padding:clamp(72px,8vw,128px) 0;border-top:1px solid var(--line);position:relative}
.section.paper,.sec.paper{background:var(--paper);color:var(--ink-text)}
.section.paper .h2,.section.paper h2,.sec.paper .h2,.sec.paper h2{color:var(--ink-text)}
.section.paper .lead,.sec.paper .lead{color:var(--mute-on-paper)}
.section.paper .eyebrow,.sec.paper .eyebrow{color:var(--mute-on-paper)}
.section.paper .small,.section.paper .micro,.sec.paper .small,.sec.paper .micro{color:var(--mute-on-paper)}
.section .wrap,.sec .wrap{max-width:var(--wrap);margin:0 auto;padding:0 var(--gut);position:relative}

/* ============================================================
   Problem cards
   ============================================================ */
.problem-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:clamp(20px,2.4vw,32px);margin-top:clamp(40px,5vw,64px)}
.problem-card{padding:clamp(28px,3.4vw,44px);border:1px solid var(--line-on-paper);border-radius:8px;background:var(--paper-2);display:flex;flex-direction:column;gap:14px;position:relative;transition:transform .3s var(--ease-out),border-color .3s var(--ease-out)}
.problem-card:hover{transform:translateY(-2px);border-color:rgba(9,11,10,.3)}
.problem-time{font-family:var(--mono);font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--mute-on-paper)}
.problem-label{font-family:var(--display);font-size:clamp(20px,1.8vw,24px);font-weight:500;letter-spacing:-.012em;color:var(--ink-text);line-height:1.2}
.problem-card p{font-size:14px;line-height:1.55;color:var(--mute-on-paper);margin:0}
.resolve{margin-top:clamp(48px,6vw,80px);padding-top:clamp(32px,4vw,48px);border-top:1px solid var(--line-on-paper);max-width:48em}
.resolve .eyebrow{margin-bottom:14px}
@media (max-width:780px){.problem-grid{grid-template-columns:1fr}}

/* ============================================================
   Connections grid
   ============================================================ */
.conn-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:clamp(20px,2vw,28px);margin-top:clamp(32px,4vw,56px)}
.conn-card{padding:clamp(28px,3vw,40px) clamp(20px,2vw,28px);border:1px solid var(--line);border-radius:8px;display:flex;flex-direction:column;gap:12px;background:rgba(243,241,234,.04);transition:border-color .3s var(--ease-out),background .3s var(--ease-out)}
.conn-card:hover{border-color:var(--line-2);background:rgba(243,241,234,.08)}
.conn-card .conn-h{font-family:var(--mono);font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:var(--light);font-weight:500}
.conn-card p{font-size:14px;line-height:1.5;color:var(--mute);margin:0}
@media (max-width:780px){.conn-grid{grid-template-columns:repeat(2,1fr)}}
@media (max-width:480px){.conn-grid{grid-template-columns:1fr}}

/* ============================================================
   Managed steps
   ============================================================ */
.steps{list-style:none;margin:clamp(40px,5vw,64px) 0 0;padding:0;display:grid;grid-template-columns:repeat(3,1fr);gap:0;border-top:1px solid var(--line-on-paper)}
.step{padding:clamp(28px,3vw,40px) clamp(24px,2.6vw,36px) clamp(28px,3vw,40px) 0;border-right:1px solid var(--line-on-paper);display:flex;flex-direction:column;gap:14px}
.step:last-child{border-right:0;padding-right:0}
.step-n{font-family:var(--mono);font-size:11px;letter-spacing:.1em;color:var(--mute-on-paper);text-transform:uppercase}
.step-h{font-family:var(--display);font-size:clamp(20px,1.8vw,24px);font-weight:500;letter-spacing:-.012em;color:var(--ink-text);margin:0;line-height:1.2}
.step p{font-size:14px;line-height:1.55;color:var(--mute-on-paper);margin:0}
.rule-block{margin:clamp(48px,6vw,80px) auto 0;padding-top:clamp(40px,5vw,64px);border-top:1px solid var(--line-on-paper);max-width:48em}
.rule-block .pull-quote{font-family:var(--display);font-style:normal;font-weight:600;font-size:clamp(32px,3.6vw,52px);letter-spacing:-.025em;line-height:1.05;color:var(--ink-text);margin:18px 0 18px;max-width:none}
.rule-block .lead{margin-top:18px}
.operator-card{margin-top:clamp(40px,5vw,64px);padding:clamp(24px,3vw,36px);border:1px solid var(--line-on-paper);border-radius:8px;display:flex;align-items:center;gap:24px;background:var(--paper-2);flex-wrap:wrap}
.op-mark{width:48px;height:48px;border-radius:50%;background:var(--ink);flex-shrink:0;position:relative}
.op-mark::after{content:"";position:absolute;inset:6px;border-radius:50%;background:radial-gradient(circle at 30% 30%,#2a2e2c,#0a0c0b 70%)}
.operator-card > div{flex:1;min-width:240px}
.op-status{font-family:var(--mono);font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--mute-on-paper);margin-left:auto}
@media (max-width:780px){.steps{grid-template-columns:1fr}.step{border-right:0;border-bottom:1px solid var(--line-on-paper);padding:24px 0}.step:last-child{border-bottom:0}.operator-card{flex-direction:column;align-items:flex-start}.op-status{margin-left:0}}

/* ============================================================
   Case grid
   ============================================================ */
.case-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:clamp(20px,2.4vw,32px);margin-top:clamp(40px,5vw,64px)}
.case-card{padding:clamp(28px,3.4vw,44px) clamp(24px,2.6vw,32px);border:1px solid var(--line);border-radius:8px;display:flex;flex-direction:column;gap:14px;background:rgba(245,245,240,.04)}
.case-n{font-family:var(--display);font-size:14px;font-style:italic;font-weight:400;color:var(--mute);letter-spacing:.04em}
.case-h{font-family:var(--display);font-size:clamp(18px,1.6vw,22px);font-weight:500;letter-spacing:-.012em;color:var(--light);line-height:1.2}
.case-card p{font-size:14px;line-height:1.55;color:var(--mute);margin:0}
@media (max-width:780px){.case-grid{grid-template-columns:1fr}}

/* ============================================================
   Pricing offer cards
   ============================================================ */
.offer-grid{display:grid;grid-template-columns:1.6fr 1fr;gap:clamp(24px,3vw,40px);margin-top:clamp(32px,4vw,56px);align-items:start}
.offer-card{padding:clamp(36px,4vw,56px);border-radius:8px;display:flex;flex-direction:column;gap:18px;background:var(--paper-2);border:1px solid var(--line-on-paper)}
.offer-card.offer-primary{background:var(--ink);color:var(--light);border-color:var(--line)}
.offer-card.offer-primary .lead,.offer-card.offer-primary .incl li,.offer-card.offer-primary .terms-line span{color:var(--mute)}
.offer-card.offer-primary .offer-price{color:var(--light)}
.offer-card.offer-primary .incl-h{color:var(--light)}
.offer-card.offer-primary .eyebrow{color:var(--mute)}
.offer-card.offer-secondary{background:var(--paper-2)}
.offer-card.offer-secondary .lead,.offer-card.offer-secondary .terms-line{color:var(--mute-on-paper)}
.offer-price{font-family:var(--display);font-size:clamp(56px,6vw,88px);font-weight:500;letter-spacing:-.04em;line-height:1;color:var(--ink-text);margin:0;display:flex;align-items:baseline;gap:6px;flex-wrap:wrap}
.offer-price small{font-family:var(--mono);font-size:14px;font-weight:400;letter-spacing:.04em;color:var(--mute-on-paper);text-transform:lowercase}
.offer-card.offer-primary .offer-price small{color:var(--mute)}
.offer-price-sm{font-family:var(--display);font-size:clamp(28px,3vw,36px);letter-spacing:-.02em;line-height:1.1}
.incl-h{font-family:var(--mono);font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:var(--ink-text);font-weight:500;margin:18px 0 0}
.offer-card.offer-primary .rule{background:rgba(243,241,234,.2)}
.offer-card .rule{background:rgba(9,11,10,.15)}
.incl{list-style:none;padding:0;margin:12px 0 0;display:flex;flex-direction:column;gap:10px}
.incl li{font-size:14px;line-height:1.5;color:var(--mute-on-paper);padding-left:18px;position:relative}
.incl li::before{content:"";position:absolute;left:0;top:11px;width:8px;height:1px;background:currentColor;opacity:.6}
.terms-line{display:flex;flex-direction:column;gap:6px;margin-top:18px;padding-top:18px;border-top:1px solid var(--line-on-paper);font-size:12px;color:var(--mute-on-paper)}
.offer-card.offer-primary .terms-line{border-top-color:rgba(243,241,234,.15);color:var(--mute)}
.terms-line span{font-family:var(--mono);letter-spacing:.04em;line-height:1.5}
@media (max-width:780px){.offer-grid{grid-template-columns:1fr}}

/* ============================================================
   Close / promise
   ============================================================ */
.close{padding-bottom:clamp(80px,10vw,160px)}
.promise-h{font-family:var(--display);font-size:clamp(36px,5vw,72px);font-weight:600;letter-spacing:-.03em;line-height:1.05;margin:0;color:var(--light);max-width:12em}
.promise-h em{font-family:var(--serif-display);font-style:italic;font-weight:400}

/* ============================================================
   Marquee strip
   ============================================================ */
.marquee{overflow:hidden;padding:clamp(20px,3vh,32px) 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);background:rgba(243,241,234,.02)}
.marquee-track{display:flex;gap:clamp(40px,6vw,80px);animation:slide 40s linear infinite;width:max-content}
.marquee-item{font-family:var(--display);font-size:clamp(18px,2vw,28px);font-weight:500;letter-spacing:-.012em;color:var(--mute);white-space:nowrap;display:inline-flex;align-items:center;gap:24px}
.marquee-item::after{content:"·";color:var(--emerald);font-size:1.5em;line-height:0}
@keyframes slide{to{transform:translateX(-50%)}}

/* ============================================================
   Generic page layouts
   ============================================================ */
main{padding:0}
.page-title{padding:clamp(80px,12vw,160px) 0 clamp(40px,6vw,72px);border-bottom:1px solid var(--line)}
.page-title .wrap{max-width:var(--wrap);margin:0 auto;padding:0 var(--gut)}
.page-title h1{font-family:var(--display);font-size:clamp(40px,6vw,84px);font-weight:600;letter-spacing:-.028em;line-height:1.02;margin:0;color:var(--light);max-width:18em}
.page-title .lead{margin-top:24px}
.page-title .meta{display:flex;gap:16px;font-family:var(--mono);font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--mute);margin-bottom:24px}

/* Sub-page hero (legacy .phero) */
.phero{padding:clamp(80px,12vw,140px) 0 clamp(40px,6vw,72px);border-bottom:1px solid var(--line)}
.phero .wrap{max-width:var(--wrap);margin:0 auto;padding:0 var(--gut)}
.phero .eyebrow{margin-bottom:24px}
.phero .h1{font-family:var(--display);font-size:clamp(36px,6vw,84px);font-weight:600;letter-spacing:-.03em;line-height:1.02;margin:0 0 22px;color:var(--light);max-width:18em}
.phero .h1 .dim{color:var(--mute);font-weight:400}
.phero .lead{margin:0;max-width:42em}
@media (max-width:640px){.phero{padding:clamp(56px,10vw,96px) 0 clamp(28px,5vw,48px)}.phero .h1{font-size:clamp(32px,9vw,52px)}}

/* Pricing-specific layout */
.price-grid{display:grid;grid-template-columns:repeat(12,1fr);gap:clamp(24px,3vw,48px);align-items:start}
.price-arg{grid-column:1/span 5}
.price-box{grid-column:6/span 7;background:var(--paper-2);border:1px solid var(--line-on-paper);border-radius:8px;padding:clamp(32px,4vw,56px)}
.price-box .micro{margin-bottom:18px}
.price{font-family:var(--display);font-size:clamp(56px,7vw,96px);font-weight:500;letter-spacing:-.04em;line-height:1;margin:0;color:var(--ink-text)}
.price small{font-family:var(--mono);font-size:14px;font-weight:400;letter-spacing:.04em;color:var(--mute-on-paper);margin-left:8px}
@media (max-width:780px){.price-grid{grid-template-columns:1fr}.price-arg,.price-box{grid-column:1/-1}}

/* Rows pattern (managed / how it works) */
.rows{display:flex;flex-direction:column;margin-top:clamp(40px,5vw,64px);border-top:1px solid var(--line-on-paper)}
.sec:not(.paper) .rows{border-top-color:var(--line)}
.row{display:grid;grid-template-columns:1fr 3fr;gap:clamp(24px,3vw,48px);padding:clamp(28px,3.4vw,44px) 0;border-bottom:1px solid var(--line-on-paper);transition:background .25s var(--ease-out)}
.sec:not(.paper) .row{border-bottom-color:var(--line)}
.row:last-child{border-bottom:0}
.row .n{font-family:var(--mono);font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--mute);padding-top:6px}
.row h3{font-family:var(--display);font-size:clamp(20px,1.8vw,28px);font-weight:500;letter-spacing:-.014em;color:var(--ink-text);margin:0 0 12px;line-height:1.2}
.sec:not(.paper) .row h3{color:var(--light)}
.row p{font-size:15px;line-height:1.55;color:var(--mute-on-paper);margin:0;max-width:42em}
