/* Drag list / detail rows */
.drag-list{display:flex;flex-direction:column;gap:1px;background:var(--line);border:1px solid var(--line);border-radius:8px;overflow:hidden}
.drag-list > *{background:var(--ink);padding:clamp(20px,2.4vw,28px);display:grid;grid-template-columns:auto 1fr auto;gap:24px;align-items:center}
.drag-list .who{font-family:var(--mono);font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--mute)}
.drag-list .res{font-family:var(--mono);font-size:11px;letter-spacing:.04em;color:var(--emerald)}

/* ============================================================
   Responsive overrides
   ============================================================ */
@media (max-width:980px){
  .sec-head{grid-template-columns:1fr;gap:24px}
