}

/* ============================================================
   Navigation — sticky blur bar
   ============================================================ */
.nav{position:sticky;top:0;z-index:50;height:var(--nav);background:rgba(5,7,8,.78);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);border-bottom:1px solid var(--line)}
.nav .wrap{max-width:var(--wrap);margin:0 auto;padding:0 var(--gut);height:100%;display:flex;align-items:center;gap:clamp(20px,3vw,40px)}
.nav .brand{display:inline-flex;align-items:center;gap:10px;color:var(--light);text-decoration:none;font-family:var(--display);font-weight:600;font-size:17px;letter-spacing:-.02em}
.nav .brand svg{width:22px;height:22px;color:var(--emerald)}
.nav-links{display:flex;gap:clamp(14px,1.6vw,24px);margin-left:auto;align-items:center}
.nav-links a{color:var(--mute);text-decoration:none;font-size:13px;font-weight:500;letter-spacing:-.005em;padding:8px 4px;position:relative;transition:color .2s var(--ease-out)}
.nav-links a:hover, .nav-links a[aria-current="page"]{color:var(--light)}
.nav-links a[aria-current="page"]::after{content:"";position:absolute;left:4px;right:4px;bottom:2px;height:1px;background:var(--emerald)}
.nav .btn{margin-left:8px}
.nav-toggle{display:none;background:none;border:0;color:var(--light);padding:8px;cursor:pointer;margin-left:auto}
.nav-toggle span{display:block;width:22px;height:1.5px;background:currentColor;position:relative}
.nav-toggle span::before,.nav-toggle span::after{content:"";position:absolute;left:0;width:22px;height:1.5px;background:currentColor;top:-7px}
.nav-toggle span::after{top:7px}
@media (max-width:920px){
  .nav-links{position:absolute;top:var(--nav);left:0;right:0;flex-direction:column;background:rgba(5,7,8,.95);backdrop-filter:blur(14px);padding:24px var(--gut);border-bottom:1px solid var(--line);display:none;align-items:stretch;gap:0;margin-left:0}
  .nav-links.open{display:flex}
  .nav-links a{padding:14px 0;border-bottom:1px solid var(--line);font-size:15px}
  .nav-links a[aria-current="page"]::after{display:none}
  .nav .btn{display:none}
  .nav-toggle{display:block}
}

/* Skip link */
.skip{position:absolute;left:-9999px;top:auto;width:1px;height:1px;overflow:hidden}
.skip:focus{position:fixed;left:16px;top:16px;width:auto;height:auto;padding:12px 16px;background:var(--emerald);color:#000;border-radius:8px;z-index:100;text-decoration:none;font-weight:600}

/* ============================================================
   Footer — editorial colophon
   ============================================================ */
.foot{background:#050708;color:var(--mute);padding:clamp(64px,8vw,120px) 0 clamp(40px,4vw,64px);border-top:1px solid var(--line)}
.foot .wrap{max-width:var(--wrap);margin:0 auto;padding:0 var(--gut)}
.foot-grid{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:clamp(32px,4vw,64px);margin-bottom:clamp(56px,7vw,96px)}
