.foot .brand{display:inline-flex;align-items:center;gap:10px;color:var(--light);font-family:var(--display);font-size:20px;font-weight:600;letter-spacing:-.02em;margin-bottom:18px}
.foot .brand svg{width:24px;height:24px;color:var(--emerald)}
.foot-grid > div:first-child p{font-size:15px;line-height:1.55;max-width:28em;color:var(--mute)}
.foot-base{display:flex;justify-content:space-between;align-items:center;padding-top:32px;border-top:1px solid var(--line);font-size:12px;color:var(--mute);font-family:var(--mono);letter-spacing:.04em}
.foot-base a{color:var(--mute);text-decoration:none}
.foot-base a:hover{color:var(--light)}
.foot-mark{font-family:var(--display);font-weight:600;font-size:clamp(80px,16vw,220px);letter-spacing:-.04em;line-height:.85;color:var(--light);opacity:.04;margin:clamp(40px,5vw,72px) 0 0;text-align:center;user-select:none;pointer-events:none}
@media (max-width:760px){
  .foot-grid{grid-template-columns:1fr 1fr;gap:40px 24px}
  .foot-base{flex-direction:column;align-items:flex-start;gap:10px}
}
